#!/usr/bin/env node
/**
 * FamilyDashBoard — Per-Card Bundle Delta CI Check
 *
 * Reads the last entry in scripts/bundle-trend.json (the baseline) and
 * compares it to the current dist/assets to detect per-card regressions.
 *
 * Fails (exit 1) when any card chunk grows by more than DELTA_THRESHOLD
 * (default 10 %) relative to the stored baseline.
 *
 * Usage:
 *   node scripts/check-card-bundle-delta.mjs
 *
 * Prerequisite: run `npx vite build` first AND have at least one entry in
 *   scripts/bundle-trend.json (generated by `node scripts/bundle-trend.mjs`).
 */

import { readdirSync, readFileSync, existsSync } from "node:fs";
import { resolve, join } from "node:path";
import { gzipSync } from "node:zlib";

const DIST_ASSETS = resolve(process.cwd(), "dist", "assets");
const TREND_FILE = resolve(process.cwd(), "scripts", "bundle-trend.json");

/** Fail CI if a card grows more than this fraction vs the baseline.
 * (v14.30.0): ratcheted 10%→8% per ROADMAP §5.1 #19. Target ≤ 5% by v15.
 * (v14.31.0): ratcheted 8%→7%. */
const DELTA_THRESHOLD = 0.07;

const CARD_PATTERNS = [
  ["weather", "weather"],
  ["stocks", "stocks"],
  ["currency", "currency"],
  ["calendar", "calendar"],
  ["hebrew-cal", "hebrew-cal"],
  ["alerts", "alerts"],
  ["motivation", "motivation"],
  ["tasks", "tasks"],
  ["system-info", "system-info"],
  ["countdown", "countdown"],
  ["news", "news"],
  ["video-news", "video-news"],
];

function gzipSize(filePath) {
  return gzipSync(readFileSync(filePath)).length;
}

function toKb(bytes) {
  return parseFloat((bytes / 1024).toFixed(1));
}

// ── Guard: dist/assets must exist ─────────────────────────────────────────
if (!existsSync(DIST_ASSETS)) {
  console.error("❌  dist/assets/ not found — run 'npx vite build' first.");
  process.exit(1);
}

// ── Guard: trend file must have at least one entry ─────────────────────────
if (!existsSync(TREND_FILE)) {
  console.log("ℹ️  No bundle-trend.json found — skipping delta check (first run).");
  process.exit(0);
}

let trend;
try {
  trend = JSON.parse(readFileSync(TREND_FILE, "utf-8"));
} catch {
  console.error("❌  Failed to parse bundle-trend.json.");
  process.exit(1);
}

if (!Array.isArray(trend) || trend.length === 0) {
  console.log("ℹ️  bundle-trend.json is empty — skipping delta check (first run).");
  process.exit(0);
}

const baseline = trend[trend.length - 1];
const baselineCards = baseline.cards ?? {};

// ── Collect current card sizes ─────────────────────────────────────────────
const jsFiles = readdirSync(DIST_ASSETS).filter((f) => f.endsWith(".js"));

/** @type {Record<string, number>} */
const currentCards = {};
for (const [label, pattern] of CARD_PATTERNS) {
  const matching = jsFiles.filter((f) => f.toLowerCase().includes(pattern));
  if (matching.length === 0) continue;
  let totalGz = 0;
  for (const f of matching) {
    totalGz += gzipSize(join(DIST_ASSETS, f));
  }
  currentCards[label] = toKb(totalGz);
}

// ── Compare ────────────────────────────────────────────────────────────────
let failed = false;
const rows = [];

for (const [card, currentKb] of Object.entries(currentCards)) {
  const baseKb = baselineCards[card];
  if (baseKb == null) {
    rows.push(`  ➕  ${card.padEnd(14)} ${currentKb} KB  (new — no baseline)`);
    continue;
  }
  const delta = (currentKb - baseKb) / baseKb;
  const deltaStr = (delta >= 0 ? "+" : "") + (delta * 100).toFixed(1) + "%";
  const sign = delta > DELTA_THRESHOLD ? "❌" : delta > 0.05 ? "⚠️ " : "✅";
  rows.push(`  ${sign}  ${card.padEnd(14)} ${baseKb} KB → ${currentKb} KB  (${deltaStr})`);
  if (delta > DELTA_THRESHOLD) {
    failed = true;
  }
}

console.log(`\nPer-card bundle delta vs baseline (${baseline.date ?? "?"}):\n`);
for (const row of rows) console.log(row);

if (failed) {
  console.error(
    `\n❌  One or more card chunks grew by more than ${DELTA_THRESHOLD * 100}%.` +
      `\n    Investigate the delta, then update the baseline with:\n` +
      `    node scripts/bundle-trend.mjs\n`,
  );
  process.exit(1);
}

console.log("\n✅  All card bundle deltas within threshold.\n");

// ── Group budget totals ─────────────────────────────────
/**
 * Group budgets: the combined gzip size of all cards in a group must not
 * exceed the budget (in KB). Fail CI with exit 1 if violated.
 */
const GROUP_BUDGETS = [
  { name: "news + video-news", cards: ["news", "video-news"], budgetKb: 28 },
  {
    name: "weather + hebrew-cal + countdown",
    cards: ["weather", "hebrew-cal", "countdown"],
    budgetKb: 38,
  },
  { name: "stocks + currency", cards: ["stocks", "currency"], budgetKb: 33 },
  { name: "calendar + alerts", cards: ["calendar", "alerts"], budgetKb: 23 },
  {
    name: "tasks + motivation + system-info",
    cards: ["tasks", "motivation", "system-info"],
    budgetKb: 23,
  },
];

let groupFailed = false;
const groupRows = [];

for (const group of GROUP_BUDGETS) {
  const totalKb = group.cards.reduce((sum, card) => {
    return sum + (currentCards[card] ?? 0);
  }, 0);
  const rounded = parseFloat(totalKb.toFixed(1));
  const over = rounded > group.budgetKb;
  const sign = over ? "❌" : "✅";
  groupRows.push(`  ${sign}  ${group.name.padEnd(36)} ${rounded} / ${group.budgetKb} KB`);
  if (over) groupFailed = true;
}

console.log("Group budget totals:\n");
for (const row of groupRows) console.log(row);
console.log("");

if (groupFailed) {
  console.error(
    "❌  One or more card groups exceeded their bundle budget.\n" +
      "    Reduce bundle size in the affected cards before releasing.\n",
  );
  process.exit(1);
}

console.log("✅  All group budgets within limits.\n");

// ── Per-card source folder delta (v14.10.0) ────────────────────────────────
// Compare cardSource sizes from bundle-trend.json baseline to current state.
// Warns on > 5% growth, fails on > 15% growth.
// Hard cap added in v14.27.0 (ROADMAP #19): any card source folder ≥ 65 KB fails CI.
// v14.30.0: ratchet 64→63 KB (largest card: weather 63.8→TBD). Target ≤ 60 KB by v15.
const SOURCE_DELTA_WARN = 0.05;
/** (v14.31.0): ratcheted 12%→10%. */
const SOURCE_DELTA_FAIL = 0.1;
/** Per-card source folder absolute cap (v14.30.0). Fail CI above this. Target ≤ 60 KB in v15. */
const SOURCE_HARD_CAP_KB = 63;
const baselineSource = baseline.cardSource ?? {};

if (Object.keys(baselineSource).length > 0) {
  const SRC_CARDS_DIR = resolve(process.cwd(), "src", "cards");
  let srcFailed = false;
  const srcRows = [];

  /** @param {string} dir @returns {number} */
  function dirSizeKb(dir) {
    if (!existsSync(dir)) return 0;
    let total = 0;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const p = join(dir, entry.name);
      if (entry.isDirectory()) total += dirSizeKb(p);
      else if (entry.isFile() && (entry.name.endsWith(".ts") || entry.name.endsWith(".css")))
        total += readFileSync(p).length;
    }
    return parseFloat((total / 1024).toFixed(1));
  }

  for (const [card, baseKb] of Object.entries(baselineSource)) {
    const cardDir = join(SRC_CARDS_DIR, card);
    const currentKb = dirSizeKb(cardDir);
    if (currentKb === 0) continue; // card dir not found — skip
    const delta = (currentKb - baseKb) / baseKb;
    const deltaStr = (delta >= 0 ? "+" : "") + (delta * 100).toFixed(1) + "%";
    const overHardCap = currentKb > SOURCE_HARD_CAP_KB;
    const sign =
      overHardCap || delta > SOURCE_DELTA_FAIL ? "❌" : delta > SOURCE_DELTA_WARN ? "⚠️ " : "✅";
    const capNote = overHardCap ? ` ⛔ over ${SOURCE_HARD_CAP_KB} KB hard cap` : "";
    srcRows.push(
      `  ${sign}  ${card.padEnd(14)} ${baseKb} KB → ${currentKb} KB  (${deltaStr})${capNote}`,
    );
    if (delta > SOURCE_DELTA_FAIL || overHardCap) srcFailed = true;
  }

  if (srcRows.length > 0) {
    console.log(
      `Per-card source folder delta vs baseline (warn >${SOURCE_DELTA_WARN * 100}%, fail >${SOURCE_DELTA_FAIL * 100}%, hard cap ${SOURCE_HARD_CAP_KB} KB):\n`,
    );
    for (const row of srcRows) console.log(row);
    console.log("");

    if (srcFailed) {
      console.error(
        "❌  One or more card source folders grew by more than " +
          `${SOURCE_DELTA_FAIL * 100}% or exceeded the ${SOURCE_HARD_CAP_KB} KB hard cap.\n` +
          "    Investigate and refactor before releasing.\n",
      );
      process.exit(1);
    }
    console.log("✅  All card source folder deltas within threshold.\n");
  }
}
